//#region src/detector/AuditManager.ts
var AuditManager = class {
	constructor(config) {
		if (config.enableAuditLog) {
			this.auditLogger = config.auditLogger || new InMemoryAuditLogger();
			this.auditUser = config.auditUser;
			this.auditSessionId = config.auditSessionId;
			this.auditMetadata = config.auditMetadata;
		}
		if (config.enableMetrics) this.metricsCollector = config.metricsCollector || new InMemoryMetricsCollector();
		if (config.enableRBAC) if (config.rbacManager) this.rbacManager = config.rbacManager;
		else if (config.role) {
			const role = getPredefinedRole(config.role);
			if (role) this.rbacManager = new RBACManager(role);
		} else this.rbacManager = new RBACManager();
	}
	getAuditLogger() {
		if (this.rbacManager && !this.rbacManager.hasPermission("audit:read")) throw new Error("[OpenRedaction] Permission denied: audit:read required");
		return this.auditLogger;
	}
	getMetricsCollector() {
		if (this.rbacManager && !this.rbacManager.hasPermission("metrics:read")) throw new Error("[OpenRedaction] Permission denied: metrics:read required");
		return this.metricsCollector;
	}
	getRBACManager() {
		return this.rbacManager;
	}
	checkPermission(permission) {
		if (!this.rbacManager) return true;
		return this.rbacManager.hasPermission(permission);
	}
	logAudit(operation, piiCount, piiTypes, textLength, processingTimeMs, redactionMode, debug) {
		if (!this.auditLogger) return;
		try {
			this.auditLogger.log({
				operation,
				piiCount,
				piiTypes,
				textLength,
				processingTimeMs,
				redactionMode,
				success: true,
				user: this.auditUser,
				sessionId: this.auditSessionId,
				metadata: this.auditMetadata
			});
		} catch (error) {
			if (debug) console.error("[OpenRedaction] Audit logging failed:", error);
		}
	}
	recordMetrics(result, processingTime, redactionMode, debug) {
		if (!this.metricsCollector) return;
		try {
			this.metricsCollector.recordRedaction(result, processingTime, redactionMode);
		} catch (error) {
			if (debug) console.error("[OpenRedaction] Metrics recording failed:", error);
		}
	}
};
